import{_ as t,o,c as a,a2 as i}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"PII Detector","description":"","frontmatter":{"title":"PII Detector"},"headers":[],"relativePath":"docs/tools/pii-detector.md","filePath":"docs/tools/pii-detector.md","lastUpdated":1790394058000}'),r={name:"docs/tools/pii-detector.md"};function s(n,e,d,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="pii-detector" tabindex="-1">PII Detector <a class="header-anchor" href="#pii-detector" aria-label="Permalink to &quot;PII Detector&quot;">​</a></h1><p>The PII Detector scans a document and reports what personal information it finds, without changing the document at all — a quick first pass to check what&#39;s in a file before deciding what to do about it.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>Drop in a PDF, CSV, or text file and click <strong>Run Detect</strong>. OrbySystems extracts the text and reports every likely personal detail it finds — names, account numbers, and similar — alongside the extracted text itself, so you can see exactly what was flagged and where.</p><h2 id="when-to-use-it-instead-of-the-pii-redactor" tabindex="-1">When to use it instead of the PII Redactor <a class="header-anchor" href="#when-to-use-it-instead-of-the-pii-redactor" aria-label="Permalink to &quot;When to use it instead of the PII Redactor&quot;">​</a></h2><p>This tool only detects and reports; it doesn&#39;t produce a cleaned-up file. Detection from text matching and context is a useful first pass, but isn&#39;t reliable enough to depend on alone — when you actually need personal information removed from a document, use the <a href="/docs/tools/pii-redactor">PII Redactor</a> instead.</p>',6)])])}const f=t(r,[["render",s]]);export{u as __pageData,f as default};
